    titleFiled: (no) => `Günlük rapor ${no}`,
    titleUpdated: (no) => `Güncellendi: ${no}`,
    crew: (n, subs) => `Sahada ${n} kişi · ${subs} taşeron`,
    headcountPending: 'Kişi sayısı bekleniyor',
    hoursPending: 'Saatler bekleniyor',
    weatherLost: (h) => `Hava nedeniyle ${h} kayıp`,
    noWeatherStop: 'Hava kaynaklı duruş yok',
